using namespace std;

string trim(const string& str) {
    size_t start = str.find_first_not_of(" \t\n\r");
    if (start == string::npos) return "";
    size_t end = str.find_last_not_of(" \t\n\r");
    return str.substr(start, end - start + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    vector<string> inputString;

    while (getline(cin, line)) {
        inputString.push_back(trim(line));
    }

    size_t currentLine = 0;

    auto readline = [&]() -> string {
        if (currentLine < inputString.size()) {
            return inputString[currentLine++];
        }
        return "";
    };

    auto output = [](const string& x) {
        cout << x << "\n";
    };

    string nStr = readline();
    int N = stoi(nStr);

    for (int test = 0; test < N; test++) {
        string fLine = readline();
        string sLine = readline();

        vector<int> f(2);
        vector<int> s(2);

        {
            istringstream iss(fLine);
            for (int i = 0; i < 2; i++) {
                iss >> f[i];
            }
        }
        {
            istringstream iss(sLine);
            for (int i = 0; i < 2; i++) {
                iss >> s[i];
            }
        }

        int result = 2;
        if (f[0] == 0 && f[1] == 0 && s[0] == 0 && s[1] == 0) {
            result = 0;
        } else if (f[0] + f[1] + s[0] + s[1] == 4) {
            result = 2;
        } else {
            result = 1;
        }

        output(to_string(result));
    }

    return 0;
}
